const money = (amount: number, currency = "UZS") => new Intl.NumberFormat("ru-RU", { maximumFractionDigits: 0 }).format(amount) + ` ${currency}`;
const currentMonth = () => new Date().toISOString().slice(0, 7);

function cn(...classes: Array<string | false | null | undefined>) { return classes.filter(Boolean).join(" "); }
function dateLabel(date: string) { return new Intl.DateTimeFormat("ru-RU", { day: "numeric", month: "short" }).format(new Date(`${date}T12:00:00`)); }
function formatTime(seconds: number) { return `${String(Math.floor(seconds / 60)).padStart(2, "0")}:${String(seconds % 60).padStart(2, "0")}`; }
function average(values: number[]) { return values.length ? Math.round(values.reduce((sum, value) => sum + value, 0) / values.length) : 0; }

function Button({ children, variant = "primary", className, onClick, type = "button", disabled = false }: { children: ReactNode; variant?: "primary" | "secondary" | "ghost" | "danger"; className?: string; onClick?: () => void; type?: "button" | "submit"; disabled?: boolean }) {
  return <button type={type} disabled={disabled} onClick={onClick} className={cn("button", `button-${variant}`, className)}>{children}</button>;
}

function Card({ children, className = "", glow = false }: { children: ReactNode; className?: string; glow?: boolean }) {
  return <section className={cn("card", glow && "card-glow", className)}>{children}</section>;
}

function ProgressRing({ value, size = 148, stroke = 10, label }: { value: number; size?: number; stroke?: number; label?: string }) {
  const radius = (size - stroke) / 2;
  const circumference = 2 * Math.PI * radius;
  const dash = circumference - (Math.min(100, value) / 100) * circumference;
  return <div className="progress-ring" style={{ width: size, height: size }}>
    <svg width={size} height={size} viewBox={`0 0 ${size} ${size}`} aria-label={`${value}%`}>
      <circle className="ring-track" cx={size / 2} cy={size / 2} r={radius} strokeWidth={stroke} />
      <circle className="ring-value" cx={size / 2} cy={size / 2} r={radius} strokeWidth={stroke} strokeDasharray={circumference} strokeDashoffset={dash} />
    </svg>
    <div className="ring-label"><strong>{value}%</strong><span>{label ?? "progress"}</span></div>
  </div>;
}

function MiniBar({ value, color }: { value: number; color: string }) { return <div className="mini-bar"><span style={{ width: `${Math.min(100, value)}%`, background: color }} /></div>; }

function EmptyState({ icon: Icon, title, text }: { icon: LucideIcon; title: string; text: string }) {
  return <div className="empty-state"><Icon size={25} /><strong>{title}</strong><span>{text}</span></div>;
}

function AppShell({ children, view, setView, theme, toggleTheme, onCommand }: { children: ReactNode; view: View; setView: (view: View) => void; theme: Theme; toggleTheme: () => void; onCommand: () => void }) {
  const [mobileOpen, setMobileOpen] = useState(false);
  const workspace = workspaceForView(view);
  const activeWorkspace = workspaceMeta[workspace];
  const workspaceNav: Array<{ id: View; label: string; icon: LucideIcon; shortcut?: string }> = workspace === "english" ? englishNavItems : [{ id: activeWorkspace.entry, label: activeWorkspace.label, icon: activeWorkspace.icon }];
  const WorkspaceIcon = activeWorkspace.icon;
  return <div className={cn("app-shell", `workspace-${workspace}`)}>
    <aside className={cn("sidebar", mobileOpen && "sidebar-open")}>
      <div className="brand"><div className="brand-mark"><WorkspaceIcon size={18} /></div><div><strong>Personal<span>Tracker</span></strong><small>{activeWorkspace.subtitle}</small></div></div>
      <div className="workspace-switcher" aria-label="Раздел приложения"><button className={cn("workspace-switch", !["finance", "sales"].includes(view) && "active")} onClick={() => setView("dashboard")}><ListChecks size={14} /><span>English Roadmap</span></button><button className={cn("workspace-switch", view === "finance" && "active finance-switch")} onClick={() => setView("finance")}><Wallet size={14} /><span>Money Tracker</span></button><button className={cn("workspace-switch", view === "sales" && "active sales-switch")} onClick={() => setView("sales")}><BriefcaseBusiness size={14} /><span>Sales / Клиенты</span></button></div>
      <div className="sidebar-section-label">Workspace</div>
      <nav className="nav-list">{workspaceNav.map(({ id, label, icon: Icon, shortcut }) => <button key={id} className={cn("nav-item", view === id && "nav-item-active")} onClick={() => { setView(id); setMobileOpen(false); }}><Icon size={18} /><span>{label}</span>{shortcut && <kbd>{shortcut}</kbd>}</button>)}</nav>
      {workspace !== "english" && <div className="related-workspace"><div className="sidebar-section-label">Связанный раздел</div><button className="nav-item related-nav" onClick={() => { setView(workspace === "sales" ? "finance" : "sales"); setMobileOpen(false); }}>{workspace === "sales" ? <Wallet size={18} /> : <BriefcaseBusiness size={18} />}<span><b>{workspace === "sales" ? "Доходы от сделок" : "Связанные сделки"}</b><small>{workspace === "sales" ? "Money Tracker" : "Sales / Клиенты"}</small></span><ArrowRight size={14} /></button></div>}
      <div className="sidebar-bottom"><div className="sidebar-section-label">Session</div><button className="nav-item" onClick={onCommand}><Command size={18} /><span>Command palette</span><kbd>⌘K</kbd></button><button className="nav-item" onClick={toggleTheme}>{theme === "dark" ? <Sun size={18} /> : <Moon size={18} />}<span>{theme === "dark" ? "Светлая тема" : "Тёмная тема"}</span></button><div className="profile-chip"><div className="avatar">Т</div><div><strong>Тимур</strong><small>A2+ → активный B1</small></div><MoreHorizontal size={16} /></div></div>
    </aside>
    <main className="main-content"><header className="topbar"><button className="icon-button mobile-menu" onClick={() => setMobileOpen((value) => !value)} aria-label="Меню"><Menu size={20} /></button><div className="breadcrumbs"><span>Personal Tracker</span><ChevronRight size={14} /><strong>{navItems.find((item) => item.id === view)?.label ?? "День"}</strong></div><div className="topbar-actions"><button className="search-trigger" onClick={onCommand}><Search size={16} /><span>Поиск по плану</span><kbd>⌘K</kbd></button><button className="icon-button" onClick={toggleTheme} aria-label="Тема">{theme === "dark" ? <Sun size={18} /> : <Moon size={18} />}</button></div></header><div className="content-wrap">{children}</div></main>
  </div>;
}

function Dashboard({ days, setView, setDay, progress, skillProgress, studyMinutes, streak, vocabulary, mistakes, tests }: { days: RoadmapDay[]; setView: (view: View) => void; setDay: (day: number) => void; progress: number; skillProgress: Record<Skill, number>; studyMinutes: number; streak: number; vocabulary: EnglishState["vocabulary"]; mistakes: EnglishState["mistakes"]; tests: EnglishState["tests"] }) {
  const moneyStore = useMoneyStore(); const salesStore = useSalesStore(); const todayKey = new Date().toISOString().slice(0, 10); const monthKey = todayKey.slice(0, 7); const salesCalls = salesStore.calls.filter((call) => call.dateTime.startsWith(todayKey)).length; const salesFollowUps = salesStore.followUps.filter((item) => item.status !== "completed" && item.date === todayKey).length; const monthIncome = moneyStore.transactions.filter((item) => item.type === "income" && item.status === "completed" && item.date.startsWith(monthKey)).reduce((sum, item) => sum + toBase(item.amount, item.currency, moneyStore), 0); const monthExpenses = moneyStore.transactions.filter((item) => item.type === "expense" && item.status === "completed" && item.date.startsWith(monthKey)).reduce((sum, item) => sum + toBase(item.amount, item.currency, moneyStore), 0);
  const todayDayNumber = getTodayDayNumber();
  const today = days.find((day) => day.dayNumber === todayDayNumber) ?? days[0];
  const completedDays = days.filter((day) => day.status === "completed").length;
  const tasksDone = days.flatMap((day) => day.tasks).filter((task) => task.completed).length;
  const nextTest = [7, 14, 21, 30, 44, 60, 74, 89, 90].find((day) => day >= todayDayNumber && !tests.some((test) => test.dayNumber === day)) ?? 90;
  return <div className="page-stack">
    <div className="page-heading"><div><p className="eyebrow"><span className="live-dot" /> 90-DAY ENGLISH OPERATING SYSTEM</p><h1>Доброе утро, Тимур.</h1><p className="subheading">Небольшой фокус сегодня — и через 90 дней рабочий английский станет привычкой.</p></div><div className="heading-actions"><Button variant="secondary" onClick={() => { setDay(today.dayNumber); setView("day"); }}><Play size={16} /> Начать день</Button><Button onClick={() => setView("roadmap")}><ListChecks size={16} /> Открыть roadmap</Button></div></div>
    <div className="hero-grid"><Card className="today-card" glow><div className="today-card-top"><div><span className="status-pill status-blue">TODAY · {dateLabel(today.date)}</span><h2>День {today.dayNumber} <span>из 90</span></h2><p>{today.title}</p></div><ProgressRing value={progress} size={132} stroke={9} label="overall" /></div><div className="today-footer"><div><span className="muted-label">Цель дня</span><strong>{today.goal}</strong></div><Button variant="secondary" onClick={() => { setDay(today.dayNumber); setView("day"); }}>Продолжить <ArrowRight size={16} /></Button></div></Card><Card className="streak-card"><div className="card-topline"><span>Consistency</span><Flame size={18} className="flame" /></div><div className="streak-number">{streak}<span>дней</span></div><p>Текущая серия без пропусков</p><div className="streak-days">{["Пн", "Вт", "Ср", "Чт", "Пт", "Сб", "Вс"].map((day, index) => <div key={day} className={cn("streak-day", index < Math.min(streak, 7) && "streak-day-active")}><span>{day}</span><i>{index < Math.min(streak, 7) ? <Check size={12} /> : ""}</i></div>)}</div><small className="muted">Лучший streak: {Math.max(streak, 0)} дней</small></Card></div>
    <div className="stat-grid"><StatCard icon={Gauge} label="Общий прогресс" value={`${progress}%`} detail="взвешенная модель" color="purple" /><StatCard icon={CheckCircle2} label="Завершено дней" value={`${completedDays} / 90`} detail={`${tasksDone} заданий выполнено`} color="green" /><StatCard icon={Clock3} label="Время обучения" value={`${Math.floor(studyMinutes / 60)}ч ${studyMinutes % 60}м`} detail="за весь период" color="blue" /><StatCard icon={Target} label="Ближайший checkpoint" value={`День ${nextTest}`} detail="контрольная точка" color="yellow" /></div><div className="workspace-pulse-grid"><Card><div className="workspace-pulse-heading"><span>English Roadmap</span><strong>{progress}%</strong></div><p>Общий прогресс обучения</p></Card><Card><div className="workspace-pulse-heading"><span>Sales</span><strong>{salesCalls} / {salesStore.dailyCallGoal}</strong></div><p>{salesFollowUps ? `${salesFollowUps} follow-up сегодня` : "Звонки за сегодня"}</p></Card><Card><div className="workspace-pulse-heading"><span>Money Tracker</span><strong>{money(monthIncome, moneyStore.baseCurrency)}</strong></div><p>Доход за текущий месяц · расходы {money(monthExpenses, moneyStore.baseCurrency)}</p></Card></div>
    <div className="two-col"><Card><SectionHeader title="Баланс навыков" action={<button className="text-button" onClick={() => setView("analytics")}>Подробная аналитика <ArrowRight size={14} /></button>} /><div className="skill-list">{(Object.keys(skillMeta) as Skill[]).map((skill) => { const meta = skillMeta[skill]; const Icon = meta.icon; return <div className="skill-row" key={skill}><div className="skill-name"><span className="skill-icon" style={{ color: meta.color, background: `${meta.color}15` }}><Icon size={15} /></span><span>{meta.label}</span></div><MiniBar value={skillProgress[skill]} color={meta.color} /><strong>{skillProgress[skill]}%</strong></div>; })}</div></Card><Card><SectionHeader title="Следующий checkpoint" action={<span className="status-pill status-yellow">День {nextTest}</span>} /><div className="checkpoint"><div className="checkpoint-icon"><Target size={22} /></div><div><strong>Срез прогресса · {nextTest === 90 ? "Final review" : "Weekly review"}</strong><p>Проверь grammar, reading, listening, writing, speaking и business English.</p></div></div><Button variant="secondary" className="full-width" onClick={() => setView("tests")}>Открыть контрольные точки <ArrowRight size={16} /></Button></Card></div>
    <div className="two-col"><Card><SectionHeader title="Последние ошибки" action={<button className="text-button" onClick={() => setView("mistakes")}>Журнал ошибок <ArrowRight size={14} /></button>} />{mistakes.length ? <div className="activity-list">{mistakes.slice(0, 3).map((mistake) => <div className="activity-row" key={mistake.id}><div className="activity-bullet error"><CircleAlert size={14} /></div><div><strong>{mistake.wrong}</strong><p>{mistake.correct}</p></div><span className={cn("status-dot", mistake.fixed && "status-dot-green")} /></div>)}</div> : <EmptyState icon={CircleAlert} title="Ошибок пока нет" text="Они появятся, когда вы начнёте практику." />}</Card><Card><SectionHeader title="Недавно добавленные выражения" action={<button className="text-button" onClick={() => setView("vocabulary")}>Открыть базу <ArrowRight size={14} /></button>} />{vocabulary.length ? <div className="phrase-list">{vocabulary.slice(0, 3).map((item) => <div className="phrase-row" key={item.id}><div><strong>{item.expression}</strong><p>{item.translation}</p></div><span className="status-pill status-teal">{item.status}</span></div>)}</div> : <EmptyState icon={BookOpen} title="База пока пустая" text="Добавьте первое полезное выражение." />}</Card></div>
  </div>;
}

function StatCard({ icon: Icon, label, value, detail, color }: { icon: LucideIcon; label: string; value: string; detail: string; color: string }) { return <Card className="stat-card"><span className={`stat-icon ${color}`}><Icon size={18} /></span><span className="muted-label">{label}</span><strong className="stat-value">{value}</strong><span className="stat-detail">{detail}</span></Card>; }
function SectionHeader({ title, action }: { title: string; action?: ReactNode }) { return <div className="section-header"><h3>{title}</h3>{action}</div>; }

function Roadmap({ days, setDay, setView }: { days: RoadmapDay[]; setDay: (day: number) => void; setView: (view: View) => void }) {
  const [filter, setFilter] = useState("all");
  const [mode, setMode] = useState<"list" | "grid">("grid");
  const filtered = days.filter((day) => filter === "all" || day.tags.includes(filter));
  const filters = ["all", "grammar", "vocabulary", "listening", "speaking", "writing", "business", "revision", "test"];
  return <div className="page-stack"><div className="page-heading compact"><div><p className="eyebrow">PROGRAM MAP · 03 AUG — 31 OCT 2026</p><h1>Roadmap</h1><p className="subheading">90 дней, разбитых на маленькие повторяемые шаги.</p></div><div className="heading-actions"><div className="segmented"><button className={mode === "grid" ? "active" : ""} onClick={() => setMode("grid")}>Карта</button><button className={mode === "list" ? "active" : ""} onClick={() => setMode("list")}>Список</button></div></div></div><Card className="filter-card"><div className="filter-scroll">{filters.map((item) => <button key={item} onClick={() => setFilter(item)} className={cn("filter-chip", filter === item && "filter-chip-active")}>{item === "all" ? "Все дни" : item}</button>)}</div><span className="muted">{filtered.length} из 90 дней</span></Card><div className={cn(mode === "grid" ? "roadmap-grid" : "roadmap-list")}>{filtered.map((day) => <DayCard key={day.id} day={day} onOpen={() => { setDay(day.dayNumber); setView("day"); }} />)}</div></div>;
}

function DayCard({ day, onOpen }: { day: RoadmapDay; onOpen: () => void }) {
  const done = day.tasks.filter((task) => task.completed).length;
  const progress = Math.round((done / day.tasks.length) * 100);
  const statusLabel: Record<RoadmapDay["status"], string> = { locked: "locked", available: "available", in_progress: "in progress", completed: "completed", missed: "missed" };
  return <button className={cn("day-card", `day-${day.status}`)} onClick={onOpen}><div className="day-card-top"><span className="day-number">{String(day.dayNumber).padStart(2, "0")}</span><span className={`status-pill status-${day.status === "completed" ? "green" : day.status === "in_progress" ? "yellow" : day.status === "available" ? "blue" : day.status === "missed" ? "red" : "gray"}`}>{statusLabel[day.status]}</span></div><div className="day-card-date">{dateLabel(day.date)} <span>· {day.estimatedMinutes} min</span></div><h3>{day.title}</h3><p>{day.description}</p><div className="tag-row">{day.tags.slice(0, 3).map((tag) => <span key={tag}>{tag}</span>)}</div><div className="day-card-bottom"><div className="mini-bar"><span style={{ width: `${progress}%` }} /></div><small>{done}/{day.tasks.length} задач</small><ChevronRight size={16} /></div></button>;
}

function DayDetail({ day, setView, onToast }: { day: RoadmapDay; setView: (view: View) => void; onToast: (message: string) => void }) {
  const { toggleTask, updateDay, finishDay, addTimerSession, addVocabulary, addMistake } = useEnglishStore();
  const [elapsed, setElapsed] = useState(0);
  const [running, setRunning] = useState(false);
  useEffect(() => { if (!running) return; const timer = window.setInterval(() => setElapsed((value) => value + 1), 1000); return () => window.clearInterval(timer); }, [running]);
  const done = day.tasks.filter((task) => task.completed).length;
  const requiredDone = day.tasks.filter((task) => task.required).every((task) => task.completed);
  const finish = () => { if (!requiredDone) { onToast("Сначала закройте все обязательные задания"); return; } if (elapsed > 0) addTimerSession(day.dayNumber, elapsed); if (finishDay(day.dayNumber)) { onToast(`День ${day.dayNumber} завершён. Отличная работа!`); setView("dashboard"); } };
  const addQuickVocab = () => { addVocabulary({ expression: "outside the original scope", translation: "за пределами исходного объёма", meaning: "not included in the original agreement", example: "This request is outside the original scope.", ownExample: "", category: "Business", level: "B1" }); onToast("Выражение добавлено в базу"); };
  const addQuickMistake = () => { addMistake({ wrong: "I am agree with you.", correct: "I agree with you.", rule: "agree is a verb, not an adjective", ownExample: "I agree with the proposed solution.", category: "Grammar" }); onToast("Ошибка добавлена в журнал"); };
  return <div className="page-stack"><div className="page-heading compact"><div><button className="back-button" onClick={() => setView("roadmap")}>← Roadmap</button><p className="eyebrow">DAY {String(day.dayNumber).padStart(2, "0")} · {dateLabel(day.date)}</p><h1>{day.title}</h1><p className="subheading">{day.description}</p></div><div className="day-progress-inline"><span>{done} / {day.tasks.length} задач</span><MiniBar value={Math.round((done / day.tasks.length) * 100)} color="#60a5fa" /></div></div><div className="day-layout"><div className="day-main"><Card><div className="goal-block"><div className="goal-icon"><Target size={20} /></div><div><span className="muted-label">Цель дня</span><strong>{day.goal}</strong></div></div><div className="divider" /><div className="theory-grid"><div><span className="muted-label">Теория</span><p>{day.grammarTopic}. Разберите правило, найдите 2–3 примера и проговорите их вслух.</p></div><div><span className="muted-label">Что искать</span><p>{day.searchQueries[0]}</p><a href={`https://www.google.com/search?q=${encodeURIComponent(day.searchQueries[0])}`} target="_blank" rel="noreferrer" className="search-link">Открыть поиск <ArrowRight size={14} /></a></div></div></Card><Card><SectionHeader title="Задания дня" action={<span className="muted">обязательные отмечены</span>} /><div className="task-list">{day.tasks.map((task) => <label key={task.id} className={cn("task-item", task.completed && "task-completed")}><input type="checkbox" checked={task.completed} onChange={() => toggleTask(day.dayNumber, task.id)} disabled={day.status === "locked"} /><span className="custom-check">{task.completed && <Check size={14} />}</span><span>{task.label}</span>{task.required && <em>required</em>}</label>)}</div></Card><Card><SectionHeader title="Черновик дня" action={<span className="autosave"><span className="save-dot" /> autosave</span>} /><label className="field-label">Заметки<textarea value={day.notes} onChange={(event) => updateDay(day.dayNumber, { notes: event.target.value })} placeholder="Что было сложным? Какие формулировки стоит повторить?" /></label><label className="field-label">Письменный ответ<textarea value={day.writtenAnswer} onChange={(event) => updateDay(day.dayNumber, { writtenAnswer: event.target.value })} placeholder="Напишите здесь ответ по теме дня..." /></label><label className="field-label">Ссылка на голосовую запись<input value={day.voiceLink} onChange={(event) => updateDay(day.dayNumber, { voiceLink: event.target.value })} placeholder="https://..." /></label></Card></div><aside className="day-side"><Card className="timer-card"><div className="card-topline"><span>Focus timer</span><TimerReset size={17} /></div><div className="timer-display">{formatTime(elapsed)}</div><div className="timer-actions"><Button onClick={() => setRunning((value) => !value)}>{running ? <Pause size={16} /> : <Play size={16} />}{running ? "Пауза" : "Старт"}</Button><Button variant="secondary" onClick={() => { if (elapsed) addTimerSession(day.dayNumber, elapsed); setElapsed(0); setRunning(false); onToast("Сессия сохранена"); }}><Check size={16} /> Сохранить</Button></div><p className="muted">Сессия сохраняется локально на этом устройстве.</p></Card><Card><SectionHeader title="Ресурсы" /><div className="resource-list">{day.resources.slice(0, 5).map((resource) => <a key={resource} href={`https://www.google.com/search?q=${encodeURIComponent(resource)}`} target="_blank" rel="noreferrer"><span><Volume2 size={15} />{resource}</span><ArrowRight size={14} /></a>)}</div></Card><Card><SectionHeader title="Быстрые записи" /><Button variant="secondary" className="full-width" onClick={addQuickVocab}><Plus size={15} /> Добавить выражение</Button><Button variant="secondary" className="full-width" onClick={addQuickMistake}><Plus size={15} /> Зафиксировать ошибку</Button></Card><Card className="finish-card"><div className="finish-icon"><Trophy size={20} /></div><strong>Готовы закрыть день?</strong><p>День будет завершён только после всех обязательных задач.</p><Button className="full-width" onClick={finish} disabled={day.status === "completed"}>{day.status === "completed" ? <><Check size={16} /> День завершён</> : <>Завершить день <ArrowRight size={16} /></>}</Button></Card></aside></div></div>;
}

function Vocabulary({ vocabulary, onToast }: { vocabulary: EnglishState["vocabulary"]; onToast: (message: string) => void }) {
  const addVocabulary = useEnglishStore((state) => state.addVocabulary);
  const reviewVocabulary = useEnglishStore((state) => state.reviewVocabulary);
  const [showForm, setShowForm] = useState(false);
  const [query, setQuery] = useState("");
  const form = useForm<VocabForm>({ resolver: zodResolver(vocabSchema), defaultValues: { category: "Work", level: "B1", ownExample: "" } });
  const due = vocabulary.filter((item) => item.nextReview <= new Date().toISOString().slice(0, 10));
  const filtered = vocabulary.filter((item) => `${item.expression} ${item.translation} ${item.category}`.toLowerCase().includes(query.toLowerCase()));
  const submit = (data: VocabForm) => { addVocabulary(data); form.reset({ category: "Work", level: "B1", ownExample: "" }); setShowForm(false); onToast("Выражение сохранено"); };
  return <div className="page-stack"><div className="page-heading compact"><div><p className="eyebrow">LANGUAGE BANK · SPACED REPETITION</p><h1>Выражения</h1><p className="subheading">Запоминайте рабочие фразы целиком и возвращайтесь к ним в правильный момент.</p></div><Button onClick={() => setShowForm((value) => !value)}><Plus size={16} /> Добавить выражение</Button></div><div className="stat-grid"><StatCard icon={BookOpen} label="Всего выражений" value={String(vocabulary.length)} detail="в персональной базе" color="purple" /><StatCard icon={RefreshCw} label="На повторение" value={String(due.length)} detail="сегодня" color="yellow" /><StatCard icon={CheckCircle2} label="Mastered" value={String(vocabulary.filter((item) => item.status === "mastered").length)} detail="закреплено" color="green" /><StatCard icon={Zap} label="B1 фокус" value={String(vocabulary.filter((item) => item.level === "B1").length)} detail="рабочая лексика" color="blue" /></div>{showForm && <Card><SectionHeader title="Новое выражение" action={<button className="icon-button" onClick={() => setShowForm(false)}><X size={16} /></button>} /><form className="form-grid" onSubmit={form.handleSubmit(submit)}><Field label="Expression" error={form.formState.errors.expression?.message}><input {...form.register("expression")} placeholder="follow up with the client" /></Field><Field label="Перевод" error={form.formState.errors.translation?.message}><input {...form.register("translation")} placeholder="связаться с клиентом повторно" /></Field><Field label="Значение"><input {...form.register("meaning")} placeholder="to contact someone again" /></Field><Field label="Пример"><input {...form.register("example")} placeholder="I will follow up with the client." /></Field><Field label="Свой пример"><input {...form.register("ownExample")} placeholder="Your sentence" /></Field><Field label="Категория"><input {...form.register("category")} /></Field><div className="form-actions"><Button type="submit"><Check size={16} /> Сохранить</Button></div></form></Card>}<Card><div className="table-toolbar"><div className="search-input"><Search size={16} /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Поиск по выражениям..." /></div><div className="status-pills"><span className="status-pill status-teal">{vocabulary.filter((item) => item.status === "learning").length} learning</span><span className="status-pill status-green">{vocabulary.filter((item) => item.status === "mastered").length} mastered</span></div></div><div className="vocab-table">{filtered.length ? filtered.map((item) => <div className="vocab-row" key={item.id}><div className="vocab-main"><strong>{item.expression}</strong><span>{item.translation}</span><small>{item.meaning}</small></div><div className="vocab-example"><span>{item.example}</span>{item.ownExample && <small>↳ {item.ownExample}</small>}</div><span className="status-pill status-teal">{item.status}</span><div className="review-actions"><button title="Повторить: знаю" onClick={() => { reviewVocabulary(item.id, true); onToast("Повторение засчитано"); }}><Check size={15} /></button><button title="Повторить позже" onClick={() => { reviewVocabulary(item.id, false); onToast("Повторение перенесено"); }}><RotateCcw size={15} /></button></div></div>) : <EmptyState icon={Search} title="Ничего не найдено" text="Попробуйте изменить поисковый запрос." />}</div></Card></div>;
}

function Field({ label, children, error }: { label: string; children: ReactNode; error?: string }) { return <label className="field-label">{label}{children}{error && <small className="field-error">{error}</small>}</label>; }

function Mistakes({ mistakes, onToast }: { mistakes: EnglishState["mistakes"]; onToast: (message: string) => void }) {
  const addMistake = useEnglishStore((state) => state.addMistake); const toggleMistake = useEnglishStore((state) => state.toggleMistake); const [showForm, setShowForm] = useState(false);
  const form = useForm<MistakeForm>({ resolver: zodResolver(mistakeSchema), defaultValues: { category: "Grammar", ownExample: "" } });
  const submit = (data: MistakeForm) => { addMistake(data); form.reset({ category: "Grammar", ownExample: "" }); setShowForm(false); onToast("Ошибка добавлена в журнал"); };
  return <div className="page-stack"><div className="page-heading compact"><div><p className="eyebrow">ERROR LOG · PATTERN RECOGNITION</p><h1>Журнал ошибок</h1><p className="subheading">Ошибки — это данные для следующей итерации, а не повод останавливать серию.</p></div><Button onClick={() => setShowForm((value) => !value)}><Plus size={16} /> Зафиксировать ошибку</Button></div><div className="two-col"><Card><SectionHeader title="Повторяющиеся паттерны" /><div className="mistake-highlight"><div className="big-number">{mistakes.length}</div><div><strong>ошибок в базе</strong><p>{mistakes.filter((item) => !item.fixed).length} требуют ещё одного повторения</p></div></div><div className="error-bars">{mistakes.slice(0, 4).map((item, index) => <div key={item.id}><span>{item.category}</span><MiniBar value={Math.max(25, 100 - index * 18)} color="#fb7185" /><small>{item.repetitions + 1}×</small></div>)}</div></Card><Card><SectionHeader title="Правило недели" /><div className="rule-card"><span className="rule-number">01</span><strong>Verb patterns</strong><p>После explain нужен объект, а затем to + человек: explain something to someone.</p><span className="status-pill status-red">needs practice</span></div></Card></div>{showForm && <Card><SectionHeader title="Новая ошибка" /><form className="form-grid" onSubmit={form.handleSubmit(submit)}><Field label="Wrong"><input {...form.register("wrong")} placeholder="He explained me." /></Field><Field label="Correct"><input {...form.register("correct")} placeholder="He explained it to me." /></Field><Field label="Rule"><input {...form.register("rule")} placeholder="explain something to someone" /></Field><Field label="Свой пример"><input {...form.register("ownExample")} placeholder="I explained the architecture to the client." /></Field><Field label="Категория"><input {...form.register("category")} /></Field><div className="form-actions"><Button type="submit"><Check size={16} /> Сохранить</Button></div></form></Card>}<Card><SectionHeader title="Все ошибки" action={<span className="muted">{mistakes.length} записей</span>} /><div className="mistake-list">{mistakes.map((item) => <div className={cn("mistake-row", item.fixed && "mistake-fixed")} key={item.id}><div className="mistake-status" onClick={() => { toggleMistake(item.id); onToast(item.fixed ? "Ошибка снова активна" : "Ошибка отмечена исправленной"); }}>{item.fixed ? <Check size={15} /> : <CircleAlert size={15} />}</div><div className="mistake-copy"><div><strong>{item.wrong}</strong><ArrowRight size={14} /><strong className="correct-text">{item.correct}</strong></div><p>{item.rule}</p><small>Пример: {item.ownExample}</small></div><span className="status-pill status-gray">{item.repetitions} повторений</span></div>)}</div></Card></div>;
}

function Writing({ entries, onToast }: { entries: EnglishState["writing"]; onToast: (message: string) => void }) {
  const addWriting = useEnglishStore((state) => state.addWriting); const [showForm, setShowForm] = useState(false); const [form, setForm] = useState({ dayNumber: 1, topic: "", original: "", corrected: "", comments: "", minutes: 20, errors: 0, score: 0 });
  const submit = (event: React.FormEvent) => { event.preventDefault(); if (!form.topic || !form.original) return; addWriting(form); setForm({ dayNumber: 1, topic: "", original: "", corrected: "", comments: "", minutes: 20, errors: 0, score: 0 }); setShowForm(false); onToast("Writing entry сохранён"); };
  return <div className="page-stack"><div className="page-heading compact"><div><p className="eyebrow">WRITING LAB · BEFORE / AFTER</p><h1>Writing</h1><p className="subheading">Сохраняйте черновик, исправленную версию и комментарии — так прогресс становится видимым.</p></div><Button onClick={() => setShowForm((value) => !value)}><Plus size={16} /> Добавить работу</Button></div><Card className="writing-overview"><div><span className="muted-label">Средняя оценка</span><strong>{average(entries.map((entry) => entry.score))}<small> / 100</small></strong></div><div><span className="muted-label">Работ сохранено</span><strong>{entries.length}</strong></div><div><span className="muted-label">Всего слов</span><strong>{entries.reduce((sum, entry) => sum + entry.wordCount, 0)}</strong></div><div><span className="muted-label">Ошибки отмечены</span><strong>{entries.reduce((sum, entry) => sum + entry.errors, 0)}</strong></div></Card>{showForm && <Card><SectionHeader title="Новая письменная работа" /><form className="form-grid" onSubmit={submit}><Field label="День"><input type="number" min="1" max="90" value={form.dayNumber} onChange={(event) => setForm({ ...form, dayNumber: Number(event.target.value) })} /></Field><Field label="Тема"><input value={form.topic} onChange={(event) => setForm({ ...form, topic: event.target.value })} placeholder="A concise professional update" /></Field><Field label="Исходный текст"><textarea value={form.original} onChange={(event) => setForm({ ...form, original: event.target.value })} /></Field><Field label="Исправленная версия"><textarea value={form.corrected} onChange={(event) => setForm({ ...form, corrected: event.target.value })} /></Field><Field label="Комментарии"><textarea value={form.comments} onChange={(event) => setForm({ ...form, comments: event.target.value })} /></Field><Field label="Оценка / 100"><input type="number" min="0" max="100" value={form.score} onChange={(event) => setForm({ ...form, score: Number(event.target.value) })} /></Field><Field label="Ошибок"><input type="number" min="0" value={form.errors} onChange={(event) => setForm({ ...form, errors: Number(event.target.value) })} /></Field><div className="form-actions"><Button type="submit"><Check size={16} /> Сохранить работу</Button></div></form></Card>}<Card><SectionHeader title="История работ" />{entries.length ? <div className="writing-list">{entries.map((entry) => <div className="writing-row" key={entry.id}><div className="writing-day">D{entry.dayNumber}</div><div><strong>{entry.topic}</strong><p>{entry.wordCount} слов · {entry.minutes} мин · {entry.errors} ошибок</p></div><div className="writing-score"><strong>{entry.score}</strong><span>/100</span></div><button className="icon-button"><ChevronRight size={17} /></button></div>)}</div> : <EmptyState icon={FileText} title="Writing history пуст" text="Сохраните первую работу после сегодняшней практики." />}</Card></div>;
}

function Speaking({ entries, onToast }: { entries: EnglishState["speaking"]; onToast: (message: string) => void }) {
  const addSpeaking = useEnglishStore((state) => state.addSpeaking); const [showForm, setShowForm] = useState(false); const [form, setForm] = useState({ dayNumber: 1, topic: "", durationSeconds: 120, source: "", pauses: 0, unknownWords: "", grammarErrors: "", comments: "", fluency: 0, grammar: 0, pronunciation: 0, vocabulary: 0, confidence: 0 });
  const submit = (event: React.FormEvent) => { event.preventDefault(); if (!form.topic) return; addSpeaking(form); setShowForm(false); onToast("Speaking entry сохранён"); };
  return <div className="page-stack"><div className="page-heading compact"><div><p className="eyebrow">SPEAKING LAB · ACTIVE PRODUCTION</p><h1>Speaking</h1><p className="subheading">Фиксируйте голосовые попытки и ставьте оценки вручную — без иллюзии, что просмотр равен навыку.</p></div><Button onClick={() => setShowForm((value) => !value)}><Plus size={16} /> Добавить попытку</Button></div><div className="stat-grid"><StatCard icon={Mic2} label="Попыток" value={String(entries.length)} detail="голосовых сессий" color="orange" /><StatCard icon={Activity} label="Средняя fluency" value={`${average(entries.map((entry) => entry.fluency))}/5`} detail="ручная оценка" color="purple" /><StatCard icon={Clock3} label="Время речи" value={`${Math.floor(entries.reduce((sum, entry) => sum + entry.durationSeconds, 0) / 60)}м`} detail="активная практика" color="blue" /><StatCard icon={Zap} label="Confidence" value={`${average(entries.map((entry) => entry.confidence))}/5`} detail="растёт с повторами" color="yellow" /></div>{showForm && <Card><SectionHeader title="Новая speaking-попытка" /><form className="form-grid" onSubmit={submit}><Field label="День"><input type="number" min="1" max="90" value={form.dayNumber} onChange={(event) => setForm({ ...form, dayNumber: Number(event.target.value) })} /></Field><Field label="Тема"><input value={form.topic} onChange={(event) => setForm({ ...form, topic: event.target.value })} placeholder="Explain a technical challenge" /></Field><Field label="Ссылка или файл"><input value={form.source} onChange={(event) => setForm({ ...form, source: event.target.value })} placeholder="https://... или путь к файлу" /></Field><Field label="Длительность, сек"><input type="number" value={form.durationSeconds} onChange={(event) => setForm({ ...form, durationSeconds: Number(event.target.value) })} /></Field><Field label="Паузы"><input type="number" value={form.pauses} onChange={(event) => setForm({ ...form, pauses: Number(event.target.value) })} /></Field><Field label="Неизвестные слова"><input value={form.unknownWords} onChange={(event) => setForm({ ...form, unknownWords: event.target.value })} /></Field><Field label="Оценки 0–5"><div className="score-grid">{(["fluency", "grammar", "pronunciation", "vocabulary", "confidence"] as const).map((key) => <label key={key}><span>{key}</span><input type="number" min="0" max="5" value={form[key]} onChange={(event) => setForm({ ...form, [key]: Number(event.target.value) })} /></label>)}</div></Field><Field label="Комментарии"><textarea value={form.comments} onChange={(event) => setForm({ ...form, comments: event.target.value })} /></Field><div className="form-actions"><Button type="submit"><Check size={16} /> Сохранить запись</Button></div></form></Card>}<Card><SectionHeader title="История speaking" />{entries.length ? <div className="speaking-list">{entries.map((entry) => <div className="speaking-row" key={entry.id}><div className="wave-icon"><Mic2 size={18} /></div><div><strong>D{entry.dayNumber} · {entry.topic}</strong><p>{formatTime(entry.durationSeconds)} · {entry.pauses} пауз · {entry.unknownWords || "слова не отмечены"}</p></div><div className="score-dots">{[entry.fluency, entry.grammar, entry.pronunciation, entry.vocabulary, entry.confidence].map((score, index) => <span key={`${entry.id}-${index}`} className={score > 0 ? "filled" : ""} />)}</div></div>)}</div> : <EmptyState icon={Mic2} title="Speaking history пуст" text="Запишите первую попытку и поставьте себе честные оценки." />}</Card></div>;
}

function Tests({ tests, onToast }: { tests: EnglishState["tests"]; onToast: (message: string) => void }) {
  const saveTest = useEnglishStore((state) => state.saveTest); const checkpoints = [7, 14, 21, 30, 44, 60, 74, 89, 90]; const [selectedDay, setSelectedDay] = useState(7); const [form, setForm] = useState({ grammar: 0, reading: 0, listening: 0, writing: 0, speaking: 0, business: 0, comments: "" }); const selected = tests.find((test) => test.dayNumber === selectedDay); const save = (event: React.FormEvent) => { event.preventDefault(); saveTest({ dayNumber: selectedDay, ...form }); onToast(`Результат дня ${selectedDay} сохранён`); };
  return <div className="page-stack"><div className="page-heading compact"><div><p className="eyebrow">CHECKPOINTS · MEASURE WHAT MATTERS</p><h1>Контрольные точки</h1><p className="subheading">Контрольные срезы помогают увидеть рост навыков, а не только количество закрытых дней.</p></div><div className="heading-stat"><strong>{average(tests.map((test) => average([test.grammar, test.reading, test.listening, test.writing, test.speaking, test.business])))}%</strong><span>средний результат</span></div></div><div className="checkpoint-grid">{checkpoints.map((day) => { const result = tests.find((test) => test.dayNumber === day); const score = result ? average([result.grammar, result.reading, result.listening, result.writing, result.speaking, result.business]) : 0; return <button className={cn("checkpoint-card", selectedDay === day && "selected", result && "has-result")} key={day} onClick={() => { setSelectedDay(day); if (result) setForm({ grammar: result.grammar, reading: result.reading, listening: result.listening, writing: result.writing, speaking: result.speaking, business: result.business, comments: result.comments }); }}><span>DAY {day}</span><strong>{result ? `${score}%` : "—"}</strong><small>{result ? "completed" : "not started"}</small></button>; })}</div><Card><SectionHeader title={`Результат · День ${selectedDay}`} action={selected ? <span className="status-pill status-green">сохранён</span> : <span className="status-pill status-gray">черновик</span>} /><form className="scores-form" onSubmit={save}><div className="score-input-grid">{(["grammar", "reading", "listening", "writing", "speaking", "business"] as const).map((key) => <label key={key}><span>{key === "business" ? "business English" : key}</span><div><input type="number" min="0" max="100" value={form[key]} onChange={(event) => setForm({ ...form, [key]: Number(event.target.value) })} /><b>%</b></div></label>)}</div><Field label="Комментарии"><textarea value={form.comments} onChange={(event) => setForm({ ...form, comments: event.target.value })} placeholder="Что получилось лучше? Где нужен следующий фокус?" /></Field><Button type="submit"><Check size={16} /> Сохранить checkpoint</Button></form></Card><Card><SectionHeader title="Динамика результатов" /><div className="chart-wrap"><ResponsiveContainer width="100%" height={260}><LineChart data={tests.map((test) => ({ day: `D${test.dayNumber}`, score: average([test.grammar, test.reading, test.listening, test.writing, test.speaking, test.business]) }))}><CartesianGrid strokeDasharray="3 3" stroke="var(--border)" vertical={false} /><XAxis dataKey="day" stroke="var(--muted)" /><YAxis domain={[0, 100]} stroke="var(--muted)" /><Tooltip contentStyle={{ background: "var(--panel-strong)", border: "1px solid var(--border)", borderRadius: 12 }} /><Line type="monotone" dataKey="score" stroke="#8b5cf6" strokeWidth={3} dot={{ fill: "#8b5cf6", r: 4 }} /></LineChart></ResponsiveContainer></div></Card></div>;
}

function Analytics({ days, progress, skillProgress, studyMinutes, vocabulary, mistakes, tests }: { days: RoadmapDay[]; progress: number; skillProgress: Record<Skill, number>; studyMinutes: number; vocabulary: EnglishState["vocabulary"]; mistakes: EnglishState["mistakes"]; tests: EnglishState["tests"] }) {
  const progressData = days.filter((_, index) => index % 7 === 6 || index === 0 || index === 89).map((day) => ({ day: `D${day.dayNumber}`, progress: Math.round((days.slice(0, day.dayNumber).filter((item) => item.status === "completed").length / day.dayNumber) * 100) }));
  const skills = (Object.keys(skillMeta) as Skill[]).map((skill) => ({ name: skillMeta[skill].label, value: skillProgress[skill], fill: skillMeta[skill].color }));
  const timeData = Array.from({ length: 7 }, (_, index) => ({ day: ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"][index], minutes: Math.round(studyMinutes / 7) + (index === 2 ? 12 : index === 5 ? 20 : 0) }));
  return <div className="page-stack"><div className="page-heading compact"><div><p className="eyebrow">ANALYTICS · REAL PROGRESS</p><h1>Аналитика</h1><p className="subheading">Взвешенная картина прогресса по действиям, навыкам и контрольным точкам.</p></div><div className="heading-stat"><strong>{progress}%</strong><span>overall progress</span></div></div><div className="stat-grid"><StatCard icon={Gauge} label="Overall progress" value={`${progress}%`} detail="50% tasks · 20% tests · 30% skills" color="purple" /><StatCard icon={CheckCircle2} label="Completed days" value={String(days.filter((day) => day.status === "completed").length)} detail="из 90" color="green" /><StatCard icon={Clock3} label="Study time" value={`${studyMinutes} мин`} detail="все таймер-сессии" color="blue" /><StatCard icon={BookOpen} label="Vocabulary" value={String(vocabulary.length)} detail={`${vocabulary.filter((item) => item.status === "mastered").length} mastered`} color="yellow" /></div><div className="analytics-grid"><Card className="wide-chart"><SectionHeader title="Прогресс по дням" /><ResponsiveContainer width="100%" height={260}><AreaChart data={progressData}><defs><linearGradient id="progressFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="#8b5cf6" stopOpacity={0.45} /><stop offset="100%" stopColor="#8b5cf6" stopOpacity={0} /></linearGradient></defs><CartesianGrid strokeDasharray="3 3" stroke="var(--border)" vertical={false} /><XAxis dataKey="day" stroke="var(--muted)" /><YAxis domain={[0, 100]} stroke="var(--muted)" /><Tooltip contentStyle={{ background: "var(--panel-strong)", border: "1px solid var(--border)", borderRadius: 12 }} /><Area type="monotone" dataKey="progress" stroke="#8b5cf6" fill="url(#progressFill)" strokeWidth={3} /></AreaChart></ResponsiveContainer></Card><Card><SectionHeader title="Баланс навыков" /><ResponsiveContainer width="100%" height={260}><BarChart data={skills} layout="vertical" margin={{ left: 10, right: 15 }}><CartesianGrid strokeDasharray="3 3" stroke="var(--border)" horizontal={false} /><XAxis type="number" domain={[0, 100]} hide /><YAxis dataKey="name" type="category" width={90} stroke="var(--muted)" tick={{ fontSize: 11 }} /><Bar dataKey="value" radius={[0, 6, 6, 0]}>{skills.map((skill) => <Cell key={skill.name} fill={skill.fill} />)}</Bar></BarChart></ResponsiveContainer></Card><Card><SectionHeader title="Время обучения" /><ResponsiveContainer width="100%" height={230}><BarChart data={timeData}><CartesianGrid strokeDasharray="3 3" stroke="var(--border)" vertical={false} /><XAxis dataKey="day" stroke="var(--muted)" /><YAxis stroke="var(--muted)" /><Tooltip contentStyle={{ background: "var(--panel-strong)", border: "1px solid var(--border)", borderRadius: 12 }} /><Bar dataKey="minutes" fill="#60a5fa" radius={[6, 6, 0, 0]} /></BarChart></ResponsiveContainer></Card><Card><SectionHeader title="Распределение фокуса" /><div className="pie-layout"><ResponsiveContainer width="55%" height={210}><PieChart><Pie data={[{ name: "Tasks", value: 50 }, { name: "Tests", value: 20 }, { name: "Speaking", value: 10 }, { name: "Writing", value: 10 }, { name: "Vocabulary", value: 5 }, { name: "Mistakes", value: 5 }]} innerRadius={52} outerRadius={76} dataKey="value" stroke="none">{["#8b5cf6", "#60a5fa", "#fb923c", "#f472b6", "#2dd4bf", "#fb7185"].map((color) => <Cell key={color} fill={color} />)}</Pie><Tooltip /></PieChart></ResponsiveContainer><div className="legend-list">{[["Tasks", 50, "#8b5cf6"], ["Tests", 20, "#60a5fa"], ["Speaking", 10, "#fb923c"], ["Writing", 10, "#f472b6"], ["Vocabulary", 5, "#2dd4bf"], ["Mistakes", 5, "#fb7185"]].map(([label, value, color]) => <div key={String(label)}><span style={{ background: String(color) }} />{label}<strong>{value}%</strong></div>)}</div></div></Card></div><div className="two-col"><Card><SectionHeader title="Слабые места" /><div className="weak-list">{(Object.keys(skillProgress) as Skill[]).sort((a, b) => skillProgress[a] - skillProgress[b]).slice(0, 3).map((skill) => <div key={skill}><span>{skillMeta[skill].label}</span><strong>{skillProgress[skill]}%</strong><MiniBar value={skillProgress[skill]} color={skillMeta[skill].color} /></div>)}</div></Card><Card><SectionHeader title="Что уже работает" /><div className="weak-list">{(Object.keys(skillProgress) as Skill[]).sort((a, b) => skillProgress[b] - skillProgress[a]).slice(0, 3).map((skill) => <div key={skill}><span>{skillMeta[skill].label}</span><strong>{skillProgress[skill]}%</strong><MiniBar value={skillProgress[skill]} color="#34d399" /></div>)}</div><p className="muted analytics-note">Tests: {tests.length} · Исправлено ошибок: {mistakes.filter((mistake) => mistake.fixed).length}</p></Card></div></div>;
}

function Finance({ expenses, budget, currency, onToast }: { expenses: EnglishState["expenses"]; budget: number; currency: string; onToast: (message: string) => void }) {
  const addExpense = useEnglishStore((state) => state.addExpense);
  const deleteExpense = useEnglishStore((state) => state.deleteExpense);
  const setMonthlyBudget = useEnglishStore((state) => state.setMonthlyBudget);
  const [showForm, setShowForm] = useState(true);
  const [selectedMonth, setSelectedMonth] = useState(currentMonth());
  const [budgetDraft, setBudgetDraft] = useState(String(budget || ""));
  const form = useForm<z.input<typeof expenseSchema>, unknown, ExpenseForm>({
    resolver: zodResolver(expenseSchema),
    defaultValues: { amount: undefined, category: "food", description: "", spentAt: new Date().toISOString().slice(0, 10), paymentMethod: "Карта", note: "" },
  });
  const monthOptions = Array.from(new Set([currentMonth(), ...expenses.map((item) => item.spentAt.slice(0, 7))])).sort().reverse();
  const monthExpenses = expenses.filter((item) => selectedMonth === "all" || item.spentAt.slice(0, 7) === selectedMonth);
  const total = monthExpenses.reduce((sum, item) => sum + item.amount, 0);
  const todayTotal = expenses.filter((item) => item.spentAt === new Date().toISOString().slice(0, 10)).reduce((sum, item) => sum + item.amount, 0);
  const remaining = budget > 0 ? budget - total : 0;
  const categoryData = expenseCategories.map((category) => ({ name: category.label, value: monthExpenses.filter((item) => item.category === category.id).reduce((sum, item) => sum + item.amount, 0), fill: category.color })).filter((item) => item.value > 0);
  const submit = (data: ExpenseForm) => { addExpense({ ...data, currency, category: data.category as ExpenseCategory }); form.reset({ amount: undefined, category: "food", description: "", spentAt: new Date().toISOString().slice(0, 10), paymentMethod: "Карта", note: "" }); onToast("Расход сохранён"); };
  const saveBudget = () => { setMonthlyBudget(Number(budgetDraft) || 0); onToast(Number(budgetDraft) > 0 ? "Месячный бюджет обновлён" : "Лимит бюджета отключён"); };
  return <div className="page-stack">
    <div className="page-heading compact"><div><p className="eyebrow">PERSONAL FINANCE · PRIVATE LEDGER</p><h1>Финансы</h1><p className="subheading">Записывай траты по факту, чтобы видеть реальную картину и спокойно сверяться с Лизой.</p></div><Button onClick={() => setShowForm((value) => !value)}><Plus size={16} /> Добавить расход</Button></div>
    <div className="stat-grid"><StatCard icon={Wallet} label="Расходы за период" value={money(total, currency)} detail={selectedMonth === currentMonth() ? "текущий месяц" : selectedMonth} color="purple" /><StatCard icon={CalendarDays} label="Сегодня" value={money(todayTotal, currency)} detail="за текущий день" color="blue" /><StatCard icon={Target} label="Остаток бюджета" value={budget > 0 ? money(remaining, currency) : "Не задан"} detail={budget > 0 ? `из ${money(budget, currency)}` : "можно задать лимит ниже"} color={remaining < 0 ? "orange" : "green"} /><StatCard icon={Activity} label="Операций" value={String(monthExpenses.length)} detail="в выбранном периоде" color="yellow" /></div>
    <div className="two-col"><Card><SectionHeader title="Период" action={<span className="status-pill status-teal">{monthExpenses.length} записей</span>} /><div className="finance-toolbar"><label className="field-label">Месяц<select value={selectedMonth} onChange={(event) => setSelectedMonth(event.target.value)}><option value="all">Вся история</option>{monthOptions.map((month) => <option key={month} value={month}>{month}</option>)}</select></label><div className="budget-control"><label className="field-label">Месячный бюджет<input type="number" min="0" value={budgetDraft} onChange={(event) => setBudgetDraft(event.target.value)} placeholder="Например, 5000000" /></label><Button variant="secondary" onClick={saveBudget}>Сохранить</Button></div></div><div className="budget-meter"><div><span>Лимит расходов</span><strong>{budget > 0 ? `${Math.round((total / budget) * 100)}%` : "без лимита"}</strong></div><MiniBar value={budget > 0 ? Math.min(100, (total / budget) * 100) : 0} color={remaining < 0 ? "#fb7185" : "#34d399"} /></div></Card><Card><SectionHeader title="Куда уходят деньги" /><div className="finance-chart">{categoryData.length ? <><ResponsiveContainer width="52%" height={190}><PieChart><Pie data={categoryData} innerRadius={48} outerRadius={72} dataKey="value" stroke="none">{categoryData.map((item) => <Cell key={item.name} fill={item.fill} />)}</Pie><Tooltip formatter={(value) => money(Number(value), currency)} /></PieChart></ResponsiveContainer><div className="legend-list">{categoryData.slice(0, 5).map((item) => <div key={item.name}><span style={{ background: item.fill }} />{item.name}<strong>{money(item.value, currency)}</strong></div>)}</div></> : <EmptyState icon={Wallet} title="Пока нет расходов" text="Добавь первую операцию — здесь появится структура твоих трат." />}</div></Card></div>
    {showForm && <Card><SectionHeader title="Новый расход" action={<button className="icon-button" onClick={() => setShowForm(false)}><X size={16} /></button>} /><form className="form-grid finance-form" onSubmit={form.handleSubmit(submit)}><Field label="Сумма" error={form.formState.errors.amount?.message}><input type="number" min="0" step="1" {...form.register("amount")} placeholder="120000" /></Field><Field label="Категория"><select {...form.register("category")}>{expenseCategories.map((category) => <option key={category.id} value={category.id}>{category.label}</option>)}</select></Field><Field label="Что купил / за что заплатил" error={form.formState.errors.description?.message}><input {...form.register("description")} placeholder="Продукты на неделю" /></Field><Field label="Дата"><input type="date" {...form.register("spentAt")} /></Field><Field label="Способ оплаты"><select {...form.register("paymentMethod")}><option>Карта</option><option>Наличные</option><option>Перевод</option><option>Другое</option></select></Field><Field label="Комментарий"><input {...form.register("note")} placeholder="Можно уточнить детали для Лизы" /></Field><div className="form-actions"><Button type="submit"><Check size={16} /> Сохранить расход</Button></div></form></Card>}
    <Card><SectionHeader title="Журнал расходов" action={<span className="muted">{money(total, currency)} за период</span>} />{monthExpenses.length ? <div className="expense-list">{monthExpenses.slice().sort((a, b) => b.spentAt.localeCompare(a.spentAt)).map((item) => { const category = expenseCategories.find((entry) => entry.id === item.category); return <div className="expense-row" key={item.id}><div className="expense-icon" style={{ color: category?.color, background: `${category?.color}18` }}><Wallet size={16} /></div><div className="expense-copy"><strong>{item.description}</strong><span>{category?.label ?? "Другое"} · {item.paymentMethod}{item.note ? ` · ${item.note}` : ""}</span></div><time>{dateLabel(item.spentAt)}</time><strong className="expense-amount">− {money(item.amount, item.currency)}</strong><button className="icon-button expense-delete" onClick={() => { deleteExpense(item.id); onToast("Расход удалён"); }} aria-label={`Удалить расход ${item.description}`}><Trash2 size={15} /></button></div>; })}</div> : <EmptyState icon={Wallet} title="Журнал пока пуст" text="Добавь расходы, чтобы видеть динамику, категории и остаток бюджета." />}</Card>
  </div>;
}

function CommandPalette({ onClose, setView, setDay }: { onClose: () => void; setView: (view: View) => void; setDay: (day: number) => void }) {
  const [query, setQuery] = useState(""); const commands = [{ label: "Открыть dashboard", key: "D", view: "dashboard" as View }, { label: "Открыть roadmap", key: "R", view: "roadmap" as View }, { label: "Открыть выражения", key: "V", view: "vocabulary" as View }, { label: "Открыть журнал ошибок", key: "M", view: "mistakes" as View }, { label: "Открыть контрольные точки", key: "T", view: "tests" as View }, { label: "Открыть Money Tracker", key: "F", view: "finance" as View }, { label: "Открыть продажи", key: "S", view: "sales" as View }]; const filtered = commands.filter((command) => command.label.toLowerCase().includes(query.toLowerCase())); return <div className="modal-backdrop" onClick={onClose}><div className="command-palette" onClick={(event) => event.stopPropagation()}><div className="command-search"><Search size={18} /><input autoFocus value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Что открыть?" /><kbd>ESC</kbd></div><div className="command-list">{filtered.map((command) => <button key={command.view} onClick={() => { setView(command.view); onClose(); }}><span>{command.label}</span><kbd>{command.key}</kbd></button>)}<button onClick={() => { setDay(getTodayDayNumber()); setView("day"); onClose(); }}><span>Перейти к сегодняшнему дню</span><kbd>↵</kbd></button></div></div></div>;
}

function Settings({ exportData, importData, resetData, resetMoney, resetSales, onToast }: { exportData: () => void; importData: (file: File) => void; resetData: () => void; resetMoney: () => void; resetSales: () => void; onToast: (message: string) => void }) {
  const [fileInput, setFileInput] = useState<HTMLInputElement | null>(null); return <div className="page-stack"><ApiSettings onToast={onToast} /><div className="page-heading compact"><div><p className="eyebrow">LOCAL CONTROL · PRIVATE BY DEFAULT</p><h1>Настройки</h1><p className="subheading">English Roadmap, Money Tracker и Sales сохраняются локально в браузере.</p></div></div><Card><SectionHeader title="Резервная копия" /><p className="muted paragraph">Экспортируйте данные перед переносом на другой компьютер. JSON содержит roadmap, Money Tracker и Sales: клиентов, звонки, предложения и follow-up.</p><div className="settings-actions"><Button onClick={exportData}><Download size={16} /> Экспортировать JSON</Button><Button variant="secondary" onClick={() => fileInput?.click()}><Upload size={16} /> Импортировать JSON</Button><input ref={setFileInput} type="file" accept="application/json" hidden onChange={(event) => { const file = event.target.files?.[0]; if (file) { importData(file); onToast("Резервная копия импортирована"); } }} /></div></Card><Card><SectionHeader title="Приватность и хранение" /><div className="privacy-grid"><div><CheckCircle2 size={18} /><span><strong>Локальное хранение</strong><small>Без внешнего backend и платных API.</small></span></div><div><RefreshCw size={18} /><span><strong>Автосохранение</strong><small>Изменения сохраняются после каждого действия.</small></span></div><div><Keyboard size={18} /><span><strong>Горячие клавиши</strong><small>D / R / V / M / T / F / S.</small></span></div></div></Card><Card className="danger-zone"><SectionHeader title="Сброс прогресса Personal Tracker" /><p className="muted paragraph">Удалится только локальный прогресс Roadmap: отметки заданий, записи, таймеры и оценки.</p><Button variant="danger" onClick={resetData}><RotateCcw size={16} /> Сбросить прогресс</Button></Card><Card className="danger-zone"><SectionHeader title="Очистить Money Tracker" /><p className="muted paragraph">Удалятся только локальные счета, операции, категории, обязательства и регулярные шаблоны Money Tracker.</p><Button variant="danger" onClick={resetMoney}><Trash2 size={16} /> Очистить Money Tracker</Button></Card><Card className="danger-zone"><SectionHeader title="Очистить Sales" /><p className="muted paragraph">Удалятся клиенты, звонки, предложения, услуги и follow-up. Данные Money Tracker не затрагиваются.</p><Button variant="danger" onClick={resetSales}><Trash2 size={16} /> Очистить Sales</Button></Card></div>;
}

export default function Home() {
  const [hydrated, setHydrated] = useState(false); const [view, setActiveView] = useState<View>("dashboard"); const [selectedDay, setSelectedDay] = useState(1); const [theme, setTheme] = useState<Theme>(() => { if (typeof window === "undefined") return "dark"; return (window.localStorage.getItem("english90-theme") as Theme | null) ?? "dark"; }); const [commandOpen, setCommandOpen] = useState(false); const [toast, setToast] = useState("");
  const store = useEnglishStore();
  const moneyStore = useMoneyStore();
  const salesStore = useSalesStore();
  const setView = useCallback((nextView: View) => { setActiveView(nextView); if (typeof window === "undefined") return; const nextWorkspace = workspaceForView(nextView); const url = new URL(window.location.href); const currentWorkspace = url.searchParams.get("workspace"); url.searchParams.set("workspace", nextWorkspace); window.history[currentWorkspace === nextWorkspace ? "replaceState" : "pushState"]({}, "", `${url.pathname}${url.search}${url.hash}`); }, []);
  useEffect(() => { void Promise.all([useEnglishStore.persist.rehydrate(), useMoneyStore.persist.rehydrate(), useSalesStore.persist.rehydrate()]).then(() => setHydrated(true)); }, []);
  useEffect(() => { const restoreWorkspace = () => { const workspace = new URLSearchParams(window.location.search).get("workspace"); if (workspace === "english" || workspace === "money" || workspace === "sales") setActiveView(viewForWorkspace(workspace)); }; restoreWorkspace(); window.addEventListener("popstate", restoreWorkspace); return () => window.removeEventListener("popstate", restoreWorkspace); }, []);
  useEffect(() => { document.documentElement.dataset.theme = theme; window.localStorage.setItem("english90-theme", theme); }, [theme]);
  useEffect(() => { const handler = (event: KeyboardEvent) => { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === "k") { event.preventDefault(); setCommandOpen(true); } if (event.key === "Escape") setCommandOpen(false); if (event.target instanceof HTMLInputElement || event.target instanceof HTMLTextAreaElement) return; const shortcuts: Record<string, View> = { d: "dashboard", r: "roadmap", v: "vocabulary", m: "mistakes", t: "tests", f: "finance", s: "sales" }; if (shortcuts[event.key.toLowerCase()]) setView(shortcuts[event.key.toLowerCase()]); }; window.addEventListener("keydown", handler); return () => window.removeEventListener("keydown", handler); }, [setView]);
  useEffect(() => { if (!toast) return; const timeout = window.setTimeout(() => setToast(""), 2800); return () => window.clearTimeout(timeout); }, [toast]);
  const progress = useMemo(() => { const daily = store.days.length ? store.days.reduce((sum, day) => sum + day.tasks.filter((task) => task.completed).length / day.tasks.length, 0) / store.days.length * 100 : 0; const tests = average(store.tests.map((test) => average([test.grammar, test.reading, test.listening, test.writing, test.speaking, test.business]))); const speaking = average(store.speaking.map((entry) => entry.fluency * 20)); const writing = average(store.writing.map((entry) => entry.score)); const vocabulary = store.vocabulary.length ? store.vocabulary.filter((item) => item.status === "mastered" || item.status === "familiar").length / store.vocabulary.length * 100 : 0; const mistakes = store.mistakes.length ? store.mistakes.filter((item) => item.fixed).length / store.mistakes.length * 100 : 0; return Math.round(daily * 0.5 + tests * 0.2 + speaking * 0.1 + writing * 0.1 + vocabulary * 0.05 + mistakes * 0.05); }, [store.days, store.tests, store.speaking, store.writing, store.vocabulary, store.mistakes]);
  const skillProgress = useMemo(() => { const result = {} as Record<Skill, number>; (Object.keys(skillMeta) as Skill[]).forEach((skill) => { const related = store.days.flatMap((day) => day.tasks.filter((task) => task.skill === skill)); result[skill] = related.length ? Math.round(related.filter((task) => task.completed).length / related.length * 100) : 0; }); return result; }, [store.days]);
  const studyMinutes = Math.round(store.timerSessions.reduce((sum, session) => sum + session.durationSeconds, 0) / 60); const activeDay = store.days.find((day) => day.dayNumber === selectedDay) ?? store.days[0];
  const exportData = () => { const blob = new Blob([JSON.stringify({ ...store, version: 1, money: { ...moneyStore, version: 1 }, sales: { ...salesStore, version: 1 } }, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(blob); const link = document.createElement("a"); link.href = url; link.download = `personal-tracker-backup-${new Date().toISOString().slice(0, 10)}.json`; link.click(); URL.revokeObjectURL(url); setToast("Общая JSON-резервная копия скачана"); };
  const importData = (file: File) => { const reader = new FileReader(); reader.onload = () => { try { const data = JSON.parse(String(reader.result)) as EnglishState & { money?: Partial<ReturnType<typeof useMoneyStore.getState>>; sales?: Partial<ReturnType<typeof useSalesStore.getState>> }; if (!Array.isArray(data.days) || data.days.length !== 90) throw new Error("invalid"); store.replaceFromBackup(data); if (data.money) useMoneyStore.getState().replaceFromBackup(data.money); if (data.sales) useSalesStore.getState().replaceFromBackup(data.sales); } catch { setToast("Не удалось импортировать этот файл"); } }; reader.readAsText(file); };
  const resetData = () => { if (window.confirm("Сбросить локальный прогресс Personal Tracker? Файлы на компьютере не будут затронуты.")) { store.resetProgress(); setToast("Прогресс сброшен"); } };
  const resetMoney = () => { if (window.confirm("Очистить все данные Money Tracker? Сначала убедись, что резервная копия сохранена." ) && window.confirm("Подтвердить окончательную очистку счетов, операций и обязательств?")) { useMoneyStore.getState().resetMoney(); setToast("Money Tracker очищен"); } };
  const resetSales = () => { if (window.confirm("Очистить клиентов, звонки, pipeline и follow-up? Сначала сохрани резервную копию." ) && window.confirm("Подтвердить окончательную очистку Sales?")) { useSalesStore.getState().resetSales(); setToast("Sales очищен"); } };
  if (!hydrated) return <div className="loading-screen"><div className="brand-mark"><Sparkles size={18} /></div><strong>Personal Tracker</strong><span>Загружаем ваш локальный workspace…</span></div>;
  const renderView = () => { if (view === "dashboard") return <Dashboard days={store.days} setView={setView} setDay={setSelectedDay} progress={progress} skillProgress={skillProgress} studyMinutes={studyMinutes} streak={store.bestStreak} vocabulary={store.vocabulary} mistakes={store.mistakes} tests={store.tests} />; if (view === "roadmap") return <Roadmap days={store.days} setDay={setSelectedDay} setView={setView} />; if (view === "day") return <DayDetail day={activeDay} setView={setView} onToast={setToast} />; if (view === "vocabulary") return <Vocabulary vocabulary={store.vocabulary} onToast={setToast} />; if (view === "mistakes") return <Mistakes mistakes={store.mistakes} onToast={setToast} />; if (view === "writing") return <Writing entries={store.writing} onToast={setToast} />; if (view === "speaking") return <Speaking entries={store.speaking} onToast={setToast} />; if (view === "tests") return <Tests tests={store.tests} onToast={setToast} />; if (view === "analytics") return <Analytics days={store.days} progress={progress} skillProgress={skillProgress} studyMinutes={studyMinutes} vocabulary={store.vocabulary} mistakes={store.mistakes} tests={store.tests} />; if (view === "finance") return <MoneyTracker onToast={setToast} />; if (view === "sales") return <SalesTracker onToast={setToast} onOpenMoney={() => setView("finance")} />; if (view === "settings") return <Settings exportData={exportData} importData={importData} resetData={resetData} resetMoney={resetMoney} resetSales={resetSales} onToast={setToast} />; return null; };
  return <><InteractiveGoldField /><AppShell view={view} setView={setView} theme={theme} toggleTheme={() => setTheme((value) => value === "dark" ? "light" : "dark")} onCommand={() => setCommandOpen(true)}>{renderView()}</AppShell>{view !== "settings" && <button className="settings-fab" onClick={() => setView("settings")} aria-label="Настройки"><Settings2 size={18} /></button>}{commandOpen && <CommandPalette onClose={() => setCommandOpen(false)} setView={setView} setDay={setSelectedDay} />}{toast && <div className="toast"><CheckCircle2 size={17} /><span>{toast}</span><button onClick={() => setToast("")}><X size={14} /></button></div>}</>;
}
